export interface IAudioWorkletContext extends IAudioContext {
  readonly audioWorklet: { addModule(moduleUrl: string): Promise<void> };
  createAudioWorkletNode(
    processorName: string,
    options?: IAudioWorkletNodeOptions,
  ): IAudioWorkletNode;
}

